NormalityTestDS <- function(
    data,
    x) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("NormalityTestDS requires jmvcore to be installed (restart may be required)")

    if ( ! missing(x)) x <- jmvcore::resolveQuo(jmvcore::enquo(x))
